.ds .ds-token-blur { padding:var(--p-space-xs); }
.ds .ds-token-blur i { width:var(--p-control-size-sm); height:var(--p-control-size-sm); border-radius:var(--p-inner-radius); background:var(--p-accent); filter:var(--p-blur-sm); }
.ds .ds-token-blur [data-token="md"] { filter:var(--p-blur-md); }
